import pandas as pd
def gain_loss_ratio(data, window):
    # Calculate gain-to-loss ratio
    gains = (data.Prior_Close * data.Characteristics.Swap / data.Characteristics.Market_CAP).rolling(window).mean()
    losses = (data.Prior_Close * data.Characteristics.Swap / data.Characteristics.Market_CAP).rolling(window).mean()
    ratio = gains / losses
    # Generate signals
