    low = data.rolling(window).min()
    high = data.rolling(window).max()
    percent_r = (data - low) / (high - low)
    signals = []
    for i in range(len(data)):
        if percent_r.iloc[i] < -0.8:
            signals.append(1)  # Buy
        elif percent_r.iloc[i] > -0.2:
