```javascript
// Canvas dimensions
const canvasWidth = 400;
const canvasHeight = 400;

// Pendulum properties
const initialAngle = 30; // degrees
const gravitationalAcceleration = 9.81; // m/s^2
const pendulumLength = 200; // pixels

// Canvas and drawing context
const canvas = document.getElementById('pendulum-canvas');
const ctx = canvas.getContext('2d');

// Pendulum state
let angle = initialAngle * Math.PI / 180;
let velocity = 0;

// Draw the pendulum
function drawPendulum() {
  ctx.clearRect(0, 0, canvasWidth, canvasHeight);
  ctx.beginPath();
  ctx.arc(canvasWidth / 2, canvasHeight / 2, pendulumLength, angle - Math.PI / 2, angle + Math.PI / 2);
  ctx.stroke();
}

// Update the pendulum state
function updatePendulum() {
  // Calculate acceleration due to gravity
  const acceleration = -gravitationalAcceleration * Math.sin(angle);

  // Update velocity and angle
  velocity += acceleration * (1 / 60); // approximate simulation step
  angle += velocity;

  // Constrain the angle to the range [-2π, 2π]
  if (angle > Math.PI) {
    angle -= 2 * Math.PI;
  } else if (angle < -Math.PI) {
    angle += 2 * Math.PI;
  }
}

// Release the pendulum
function releasePendulum() {
  angle = initialAngle * Math.PI / 180;
  velocity = 0;
}

// Main loop
function animate() {
  updatePendulum();
  drawPendulum();
  requestAnimationFrame(animate);
}

// Initialize the animation
animate();

// Update the input field value
document.getElementById('initial-angle').addEventListener('change', (e) => {
  initialAngle = parseInt(e.target.value);
  releasePendulum();
});
```
