				snapshotsToDelete = append(snapshotsToDelete, *snapshot.SnapshotId)
			}
		case "daily":
			if len(snapshotsToDelete) >= 10 {
				snapshotsToDelete = append(snapshotsToDelete, *snapshot.SnapshotId)
			}
		case "weekly":
			if len(snapshotsToDelete) >= 4 {
				snapshotsToDelete = append(snapshotsToDelete, *snapshot.SnapshotId)
			}
		case "yearly":
			snapshotsToDelete = append(snapshotsToDelete, *snapshot.SnapshotId)
		}
	}

	// Delete snapshots
	for _, snapshotId := range snapshotsToDelete {
