  gpioSetup(12, PI_OUTPUT);

  // Set the output high (on)
  gpioWrite(12, PI_HIGH);

  // Wait for 2 seconds
  usleep(2000000);

  // Set the output low (off)
  gpioWrite(12, PI_LOW);

  // Wait for 2 seconds
  usleep(2000000);

  // Clean up
  gpioTerminate();

  return 0;
}
